def shell(file,title,desc,body):
 path=D/file;path.parent.mkdir(parents=True,exist_ok=True);canonical=SITE_URL+seo.page_path(file)
 banner_script='<script src="/assets/banner.js" defer></script>' if file in ['index.html','banner.html'] else ''
 if sanity.configured() and (file in ['index.html','news.html','post.html'] or file.startswith('news/')):banner_script+=f'<meta name="cbm-sanity" content="{sanity.PROJECT}:{html.escape(sanity.DATASET,quote=True)}"><meta name="cbm-built" content="{" ".join(p["slug"] for p in POSTS)}"><script src="/assets/news.js" defer></script>'
 text=f'''<!doctype html><html lang="en-NG"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | City Boy Movement Ogun State</title><meta name="description" content="{html.escape(desc)}"><meta name="theme-color" content="#00612B"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title)} | CBM Ogun"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:image" content="{SITE_URL}/assets/social-cover.png"><meta property="og:url" content="{canonical}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Montserrat:wght@500;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/app.js" defer></script>{banner_script}</head><body id="top">{header(file)}<main id="main">{body}</main>{footer()}</body></html>'''
 text=enhance(file,body,text,SITE_URL,ROOT)
 path.write_text(text)
def intro(k,h,p):return f'<section class="page-intro"><div class="wrap"><div class="breadcrumb"><a href="/index.html">Home</a><span>/</span>{k}</div><span class="eyebrow">{k}</span><h1>{h}</h1><p class="lede">{p}</p></div></section>'
def faq(items):return '<div class="faqs">'+''.join(f'<details><summary>{q}<span>{icon("plus")}</span></summary><div class="answer">{a}</div></details>' for q,a in items)+'</div>'
def programcard(p):return f'<a class="programme-card" href="/programmes/{p[0]}.html"><div class="card-top"><span>{p[1]} / FOCUS AREA</span>{icon(p[5])}</div><h3>{p[2]}</h3><p>{p[4]}</p><span class="text-link">Explore focus area {icon()}</span></a>'
def home_news(posts):
 # Homepage: newest post as the lead story, the next two as compact rows beside it.
 if not posts:return '<div class="home-news" id="home-posts"></div>'
 def meta(p,pill):
  cat=f'<span class="post-pill">{html.escape(p["category"])}</span>' if pill else f'<span class="home-cat">{html.escape(p["category"])}</span>'
  return '<div class="post-meta">'+(' ' if pill else ' · ').join(x for x in [cat,post_date(p)] if x)+'</div>'
 lead=posts[0];more=f'<span class="text-link" aria-hidden="true">Read more {icon()}</span>'
 html_lead=f'<article class="home-lead"><div class="home-lead-media">{post_thumb(lead,1000,False)}</div><div class="home-lead-body">{meta(lead,True)}<h3><a href="{post_url(lead)}">{html.escape(lead["title"])}</a></h3><p>{html.escape(lead["excerpt"])}</p>{more}</div></article>'
 items=''.join(f'<article class="home-item"><div class="home-item-media">{post_thumb(p,500)}</div><div class="home-item-body">{meta(p,False)}<h3><a href="{post_url(p)}">{html.escape(p["title"])}</a></h3><p>{html.escape(p["excerpt"])}</p>{more}</div></article>' for p in posts[1:3])
 return f'<div class="home-news" id="home-posts">{html_lead}'+(f'<div class="home-news-list">{items}</div>' if items else '')+'</div>'
